function main(stream) {
  // Titan Forge accounts (public addresses, filled in from GET /api/status at render time).
  const WATCH = new Set(__TF_ACCOUNTS__);
  const out = [];
  const ledgers = Array.isArray(stream.data) ? stream.data : [stream.data];
  for (const l of ledgers) {
    if (!l) continue;
    const txs = Array.isArray(l.transactions) ? l.transactions : Array.isArray(l) ? l : [];
    for (const t of txs) {
      const tx = t.tx_json || t.tx || t;
      const meta = t.meta || t.metaData || {};
      const touched = new Set([tx.Account, tx.Destination].filter(Boolean));
      for (const n of meta.AffectedNodes || []) {
        const node = n.ModifiedNode || n.CreatedNode || n.DeletedNode || {};
        const f = node.FinalFields || node.NewFields || {};
        if (f.Account) touched.add(f.Account);
      }
      const hit = [...touched].filter((a) => WATCH.has(a));
      if (!hit.length) continue;
      out.push({ hash: t.hash || tx.hash, ledger: l.ledger_index || t.ledger_index || null, type: tx.TransactionType, result: meta.TransactionResult || null, accounts: hit });
    }
  }
  return out.length ? { titanForge: out } : null;
}
